import java.util.Scanner;

public class Main {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        int nums[] = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = sc.nextInt();
        }

        int idx = 0;
        int startCount = 0;
        int emptySeats = k;

        while (idx < n) {
            if (nums[idx] <= emptySeats) {
                emptySeats -= nums[idx];
            } else {
                startCount++;
                emptySeats = k - nums[idx];
            }
            idx++;
        }

        if (emptySeats != k) {
            startCount++;
        }

        System.out.println(startCount);
    }
}
